SELECT ts.TEST_SET_UUID AS id,
       ts.TEST_SET_ID,
       CONCAT(ts.TEST_SET_ID, ' - ', ts.TEST_SET_NAME) AS value, 
       CONCAT(ts.TEST_SET_ID, ' - ', ts.TEST_SET_NAME) AS label,
       CONCAT(ts.TEST_SET_ID, ' - ', ts.TEST_SET_NAME) AS name
FROM TEST_SET ts
WHERE ts.FUNCTIONAL_AREA_UUID =:APP_LOGGED_IN_FUNTIONAL_AREA_ID
  AND ts.TEST_SET_TYPE IN ('User Action', 'Functional', 'Page Navigation')
  AND (ts.IS_ORPHAN_TEST_SET != 'Yes' OR ts.IS_ORPHAN_TEST_SET IS NULL)
  AND :TEST_SUITE_CREATION_TYPE = 'Manual'
AND ts.TEST_SET_UUID in (select TEST_SET_UUID from TEST_CASE tc  where  tc.FUNCTIONAL_AREA_UUID =:APP_LOGGED_IN_FUNTIONAL_AREA_ID AND tc.TEST_CASE_STATUS = 'COMMITTED')
UNION
SELECT ts.TEST_SET_UUID AS id,
