       CONCAT(ts.TEST_SET_ID, ' - ', ts.TEST_SET_NAME) AS value, 
       CONCAT(ts.TEST_SET_ID, ' - ', ts.TEST_SET_NAME) AS label,
       CONCAT(ts.TEST_SET_ID, ' - ', ts.TEST_SET_NAME) AS name
FROM TEST_SET ts
WHERE ts.FUNCTIONAL_AREA_UUID =:APP_LOGGED_IN_FUNTIONAL_AREA_ID
  AND ts.TEST_SET_TYPE IN ('User Action', 'Functional', 'Page Navigation')
  AND :TEST_SUITE_CREATION_TYPE = 'System'
