SELECT ts.TEST_SET_UUID, ts.TEST_SET_ID, ted.TEST_RUN_UUID, ts.TEST_SET_NAME, ted.TEST_SET_EXECUTION_DATE, ted.TEST_SUITE_UUID, ted.TEST_SET_EXECUTION_STATUS, CONCAT(ROUND(ted.TEST_SET_DURATION / 1000.0, 3), ' sec') AS TEST_SET_DURATION FROM TEST_EXECUTION_DETAIL ted JOIN TEST_SET ts ON ted.TEST_SET_UUID = ts.TEST_SET_UUID WHERE ted.TEST_RUN_UUID = :TEST_RUN_UUID AND ted.TEST_SUITE_UUID = :TEST_SUITE_UUID GROUP BY ts.TEST_SET_UUID, ts.TEST_SET_ID, ted.TEST_RUN_UUID, ts.TEST_SET_NAME, ted.TEST_SET_EXECUTION_DATE, ted.TEST_SUITE_UUID, ted.TEST_SET_EXECUTION_STATUS, ted.TEST_SET_DURATION ORDER BY ted.TEST_SET_EXECUTION_DATE ASC;













SELECT uuid() as uuid, 'Test Case' as 'Object Type', '' as 'Unique ID', concat(tc.TEST_CASE_ID, ' - ', tc.TEST_CASE_NAME) as Name, 'Functional' as Type, '' as Priority, tc.TEST_CASE_EXECUTON_TYPE as Method, '' as 'Last Build', '' as 'Last Run', '' as 'Work Product', '' as Description, '' as Notes, '' as Objective, tcd.TEST_CASE_PRE_CONDITION as 'Pre Conditions', tcd.TEST_CASE_USER_INPUT as 'Validation Input', tcd.TEST_CASE_EXPECTED_RESULT as 'Validation Expected Result', tcd.TEST_CASE_ACTUAL_RESULT as 'Post Conditions', ius.REQUIREMENT_TITLE_UUID, ius.REQUIREMENT_UUID, ius.CONDITION_SATISFACTION_UUID, tcr.TEST_CASE_UUID, tc.FUNCTIONAL_AREA_UUID FROM IMPACTED_USER_STORY ius JOIN TEST_CASE_REQUIREMENT tcr ON ius.REQUIREMENT_UUID = tcr.REQUIREMENT_UUID JOIN TEST_CASE tc ON tc.TEST_CASE_UUID = tcr.TEST_CASE_UUID JOIN TEST_CASE_DESCRIPTION tcd ON tc.TEST_CASE_UUID = tcd.TEST_CASE_UUID WHERE ius.USER_STORY_UUID=:USER_STORY_UUID GROUP BY tc.TEST_CASE_UUID, tc.TEST_CASE_ID, tc.TEST_CASE_NAME, tc.TEST_CASE_EXECUTON_TYPE, tc.FUNCTIONAL_AREA_UUID, tcd.TEST_CASE_PRE_CONDITION, tcd.TEST_CASE_USER_INPUT, tcd.TEST_CASE_EXPECTED_RESULT, tcd.TEST_CASE_ACTUAL_RESULT, ius.REQUIREMENT_TITLE_UUID, ius.REQUIREMENT_UUID, ius.CONDITION_SATISFACTION_UUID, tcr.TEST_CASE_UUID;






