  AND USER_STORY_SOURCE_ID != '' THEN CONCAT(
    USER_STORY_SOURCE_ID, ' - ', USER_STORY_NAME
  ) ELSE USER_STORY_NAME END AS US_NAME, 
  USER_STORY_UUID, 
  USER_STORY_SOURCE_ID, 
  USER_STORY_ID, 
  USER_STORY_NAME, 
  USER_STORY_STATUS, 
  DEVELOPMENT_ACCEPTED_TS, 
  'UserStory_Requirements' as GRID_NAME, 
  USER_STORY_SOURCE_TYPE 
FROM 
  USER_STORY 
WHERE 
  FUNCTIONAL_AREA_UUID =:APP_LOGGED_IN_FUNTIONAL_AREA_ID 
ORDER BY 
  USER_STORY_ID DESC;


SELECT 
  'User Story Test Set' as GRID_NAME, 
  'TEST_SET' as SOURCE_TYPE, 
  ts.TEST_SET_UUID, 
  ts.TEST_SET_ID, 
  ts.TEST_SET_NAME, 
  ts.PROCESS_UUID, 
  ts.PAGE_UUID, 
  ts.VIEW_UUID, 
  ts.USER_ACTION_UUID, 
  ts.AE_INSERT_ID, 
  ts.AE_UPDATE_ID, 
  ts.AE_INSERT_TS, 
  ts.AE_UPDATE_TS, 
  ts.AE_TRANSACTION_ID, 
  ts.FUNCTIONAL_AREA_UUID, 
  ts.TAGS_UUID, 
  ts.TEST_SET_TYPE, 
  ts.USER_STORY_UUID,
  us.USER_STORY_ID as ID,
  CASE WHEN us.USER_STORY_SOURCE_ID IS NOT NULL 
  AND us.USER_STORY_SOURCE_ID != '' THEN CONCAT(
    us.USER_STORY_SOURCE_ID, ' - ', us.USER_STORY_NAME
  ) ELSE us.USER_STORY_NAME END AS US_NAME, 
  us.USER_STORY_SOURCE_ID, 
  us.USER_STORY_STATUS, 
  us.DEVELOPMENT_ACCEPTED_TS, 
  USER_STORY_SOURCE_TYPE
FROM 
  TEST_SET ts JOIN USER_STORY us ON ts.USER_STORY_UUID = us.USER_STORY_UUID
WHERE 
  ts.TEST_SET_TYPE = 'User Story' 
  AND ts.FUNCTIONAL_AREA_UUID =:APP_LOGGED_IN_FUNTIONAL_AREA_ID 
order by 
  ts.TEST_SET_ID desc;




SELECT 
  'LinkedUnitFunctionalTestCases' as tab, 
  null as TEST_CASE_STEP_UUID, 
  :TEST_CASE_UUID as TEST_CASE_UUID, 
  caseReq.TEST_CASE_REQUIREMENT_UUID, 
  caseReq.REQUIREMENT_TITLE_UUID, 
  concat(
    rt.REQUIREMENT_TITLE_ID, ' - ', rt.REQUIREMENT_TITLE
  ) as REQUIREMENT_TITLE_NAME, 
  ip.ASSOCIATION_TYPE, 
  caseReq.REQUIREMENT_UUID, 
  rr.REQUIREMENT_ID, 
  caseReq.CONDITION_SATISFACTION_UUID, 
  caseReq.PROCESS_UUID, 
  caseReq.VIEW_UUID, 
  caseReq.USER_ACTION_UUID, 
  caseReq.FUNCTIONAL_AREA_UUID, 
  rs.PARENT_REQUIREMENT_SET_UUID,
  Tcase.USER_STORY_UUID as TEST_CASE_USER_STORY_UUID, 
  CASE WHEN rs.REQUIREMENT_SET_UUID IS NOT NULL THEN (
    SELECT 
      concat(
        rs.REQUIREMENT_SET_ID, ' - ', rs.REQUIREMENT_SET_NAME
      ) as REQUIREMENT_SET_UUID
  ) WHEN rs.REQUIREMENT_SET_UUID IS NULL THEN (
    SELECT 
      '' as REQUIREMENT_SET_UUID
  ) END AS REQUIREMENT_SET_UUID 
from 
  TEST_CASE_REQUIREMENT caseReq, 
  TEST_CASE Tcase, 
  IMPACTED_PROCESS ip, 
  REQUIREMENT_TITLE rt, 
  REQUIREMENT rr 
  left JOIN REQUIREMENT_SET rs ON rs.REQUIREMENT_SET_UUID = rr.REQUIREMENT_SET_UUID 
where 
  rt.REQUIREMENT_TITLE_UUID = rr.REQUIREMENT_ASSOCIATION_UUID 
  and rr.REQUIREMENT_UUID = caseReq.REQUIREMENT_UUID 
  and caseReq.IMPACTED_PROCESS_UUID = ip.IMPACTED_PROCESS_UUID 
  and Tcase.TEST_CASE_UUID = caseReq.TEST_CASE_UUID 
  and caseReq.TEST_CASE_UUID =:TEST_CASE_UUID 
  and ip.ASSOCIATION_TYPE in ('FEATURE') 
union 
SELECT 
  'LinkedUnitFunctionalTestCases' as tab, 
  null as TEST_CASE_STEP_UUID, 
  :TEST_CASE_UUID as TEST_CASE_UUID, 
  caseReq.TEST_CASE_REQUIREMENT_UUID, 
  caseReq.REQUIREMENT_TITLE_UUID, 
  concat (
    pr.PROCESS_ID, ' - ', pr.PROCESS_NAME, 
    ', ', pg.PAGE_ID, ' - ', pg.PAGE_NAME, 
    ', ', uva.USER_ACTION_ID, ' - ', 
    uva.USER_ACTION_NAME
  ) as REQUIREMENT_TITLE_NAME, 
  ip.ASSOCIATION_TYPE, 
  caseReq.REQUIREMENT_UUID, 
  rr.REQUIREMENT_ID, 
  caseReq.CONDITION_SATISFACTION_UUID, 
  caseReq.PROCESS_UUID, 
  caseReq.VIEW_UUID, 
  caseReq.USER_ACTION_UUID, 
  caseReq.FUNCTIONAL_AREA_UUID, 
  rs.PARENT_REQUIREMENT_SET_UUID,
  Tcase.USER_STORY_UUID as TEST_CASE_USER_STORY_UUID, 
  concat(
    rs.REQUIREMENT_SET_ID, ' - ', rs.REQUIREMENT_SET_NAME
  ) as REQUIREMENT_SET_UUID 
from 
  TEST_CASE_REQUIREMENT caseReq, 
  TEST_CASE Tcase, 
  IMPACTED_PROCESS ip, 
  PROCESS pr, 
  PAGE pg, 
  VIEW_USER_ACTION uva, 
  REQUIREMENT rr 
  left JOIN REQUIREMENT_SET rs ON rs.REQUIREMENT_SET_UUID = rr.REQUIREMENT_SET_UUID 
where 
  pr.PROCESS_UUID = ip.PROCESS_UUID 
  and pg.PAGE_UUID = ip.PAGE_UUID 
  and uva.USER_ACTION_UUID = ip.USER_ACTION_UUID 
  and rr.REQUIREMENT_UUID = caseReq.REQUIREMENT_UUID 
  and caseReq.IMPACTED_PROCESS_UUID = ip.IMPACTED_PROCESS_UUID 
  and Tcase.TEST_CASE_UUID = caseReq.TEST_CASE_UUID 
  and caseReq.TEST_CASE_UUID =:TEST_CASE_UUID 
  and ip.ASSOCIATION_TYPE in ('PAGE-EVENT') 
order by 
  REQUIREMENT_ID desc;



SELECT 'LinkedUnitFunctionalTestCases' as tab, null as TEST_CASE_STEP_UUID, :TEST_CASE_UUID as TEST_CASE_UUID, caseReq.TEST_CASE_REQUIREMENT_UUID, caseReq.REQUIREMENT_TITLE_UUID, concat( rt.REQUIREMENT_TITLE_ID, ' - ', rt.REQUIREMENT_TITLE ) as REQUIREMENT_TITLE_NAME, ip.ASSOCIATION_TYPE, caseReq.REQUIREMENT_UUID, rr.REQUIREMENT_ID, caseReq.CONDITION_SATISFACTION_UUID, caseReq.PROCESS_UUID, caseReq.VIEW_UUID, caseReq.USER_ACTION_UUID, caseReq.FUNCTIONAL_AREA_UUID, rs.PARENT_REQUIREMENT_SET_UUID, Tcase.USER_STORY_UUID as TEST_CASE_USER_STORY_UUID, CASE WHEN rs.REQUIREMENT_SET_UUID IS NOT NULL THEN ( SELECT concat( rs.REQUIREMENT_SET_ID, ' - ', rs.REQUIREMENT_SET_NAME ) as REQUIREMENT_SET_UUID ) WHEN rs.REQUIREMENT_SET_UUID IS NULL THEN ( SELECT '' as REQUIREMENT_SET_UUID ) END AS REQUIREMENT_SET_UUID from TEST_CASE_REQUIREMENT caseReq, TEST_CASE Tcase, IMPACTED_PROCESS ip, REQUIREMENT_TITLE rt, REQUIREMENT rr left JOIN REQUIREMENT_SET rs ON rs.REQUIREMENT_SET_UUID = rr.REQUIREMENT_SET_UUID where rt.REQUIREMENT_TITLE_UUID = rr.REQUIREMENT_ASSOCIATION_UUID and rr.REQUIREMENT_UUID = caseReq.REQUIREMENT_UUID and caseReq.IMPACTED_PROCESS_UUID = ip.IMPACTED_PROCESS_UUID and Tcase.TEST_CASE_UUID = caseReq.TEST_CASE_UUID and caseReq.TEST_CASE_UUID =:TEST_CASE_UUID and ip.ASSOCIATION_TYPE in ('FEATURE') union SELECT 'LinkedUnitFunctionalTestCases' as tab, null as TEST_CASE_STEP_UUID, :TEST_CASE_UUID as TEST_CASE_UUID, caseReq.TEST_CASE_REQUIREMENT_UUID, caseReq.REQUIREMENT_TITLE_UUID, concat ( pr.PROCESS_ID, ' - ', pr.PROCESS_NAME, ', ', pg.PAGE_ID, ' - ', pg.PAGE_NAME, ', ', uva.USER_ACTION_ID, ' - ', uva.USER_ACTION_NAME ) as REQUIREMENT_TITLE_NAME, ip.ASSOCIATION_TYPE, caseReq.REQUIREMENT_UUID, rr.REQUIREMENT_ID, caseReq.CONDITION_SATISFACTION_UUID, caseReq.PROCESS_UUID, caseReq.VIEW_UUID, caseReq.USER_ACTION_UUID, caseReq.FUNCTIONAL_AREA_UUID, rs.PARENT_REQUIREMENT_SET_UUID, Tcase.USER_STORY_UUID as TEST_CASE_USER_STORY_UUID, concat( rs.REQUIREMENT_SET_ID, ' - ', rs.REQUIREMENT_SET_NAME ) as REQUIREMENT_SET_UUID from TEST_CASE_REQUIREMENT caseReq, TEST_CASE Tcase, IMPACTED_PROCESS ip, PROCESS pr, PAGE pg, VIEW_USER_ACTION uva, REQUIREMENT rr left JOIN REQUIREMENT_SET rs ON rs.REQUIREMENT_SET_UUID = rr.REQUIREMENT_SET_UUID where pr.PROCESS_UUID = ip.PROCESS_UUID and pg.PAGE_UUID = ip.PAGE_UUID and uva.USER_ACTION_UUID = ip.USER_ACTION_UUID and rr.REQUIREMENT_UUID = caseReq.REQUIREMENT_UUID and caseReq.IMPACTED_PROCESS_UUID = ip.IMPACTED_PROCESS_UUID and Tcase.TEST_CASE_UUID = caseReq.TEST_CASE_UUID and caseReq.TEST_CASE_UUID =:TEST_CASE_UUID and ip.ASSOCIATION_TYPE in ('PAGE-EVENT') order by REQUIREMENT_ID desc;








SELECT 
  'AllUnitFunctionalTestCases' as tab, 
  'Link' as Action, 
  null as TEST_CASE_STEP_UUID, 
  :TEST_CASE_UUID as TEST_CASE_UUID, 
  IMPACTED_PROCESS_UUID, 
  null as TEST_CASE_REQUIREMENT_UUID, 
  concat(
    rt.REQUIREMENT_TITLE_ID, ' - ', rt.REQUIREMENT_TITLE
  ) as REQUIREMENT_TITLE_NAME, 
  rt.REQUIREMENT_TITLE_UUID, 
  process.ASSOCIATION_TYPE, 
  process.REQUIREMENT_UUID, 
  rr.REQUIREMENT_ID as REQUIREMENT_ID, 
  process.CONDITION_SATISFACTION_UUID, 
  process.PROCESS_UUID, 
  process.VIEW_UUID, 
  process.USER_ACTION_UUID, 
  stepUser.FUNCTIONAL_AREA_UUID, 
  rs.PARENT_REQUIREMENT_SET_UUID, 
  stepUser.USER_STORY_UUID as TEST_CASE_USER_STORY_UUID, 
  concat(
    rs.REQUIREMENT_SET_ID, ' - ', rs.REQUIREMENT_SET_NAME
  ) as REQUIREMENT_SET_UUID 
from 
  IMPACTED_PROCESS process, 
  TEST_CASE stepUser, 
  REQUIREMENT_TITLE rt, 
  REQUIREMENT rr 
  left JOIN REQUIREMENT_SET rs ON rs.REQUIREMENT_SET_UUID = rr.REQUIREMENT_SET_UUID 
where 
  rt.REQUIREMENT_TITLE_UUID = rr.REQUIREMENT_ASSOCIATION_UUID 
  and rr.REQUIREMENT_UUID = process.REQUIREMENT_UUID 
  and process.USER_ACTION_UUID =:USER_ACTION_UUID 
  and stepUser.TEST_CASE_UUID =:TEST_CASE_UUID 
  and ASSOCIATION_TYPE in ('FEATURE') 
  and process.IMPACTED_PROCESS_UUID not in (
    SELECT 
      process.IMPACTED_PROCESS_UUID 
    FROM 
      IMPACTED_PROCESS process, 
      TEST_CASE_REQUIREMENT tcr 
    where 
      process.IMPACTED_PROCESS_UUID = tcr.IMPACTED_PROCESS_UUID 
      and tcr.TEST_CASE_UUID =:TEST_CASE_UUID
  ) 
union 
SELECT 
  'AllUnitFunctionalTestCases' as tab, 
  'Link' as Action, 
  null as TEST_CASE_STEP_UUID, 
