SELECT 
  'Unit Functional Test Set' as PARENT_GRID_NAME, 
  'LinkedTestCases' as LINKED_TEST_CASE_GRID, 
  'AllRequirement' as ALL_REQ_GRID,
  'TEST_CASE' as SOURCE_TYPE, 
  'Copy Test Case' as TEST_CASE_FORM_TYPE,
  'Copy Test Case Steps' as TEST_CASE_STEP_FORM_TYPE,
  :TEST_SET_NAME as TEST_SET_NAME,
  tc.TEST_CASE_UUID, 
  tc.TEST_CASE_ID, 
  tc.TEST_CASE_NAME, 
  tc.AE_INSERT_ID, 
  tc.AE_UPDATE_ID, 
  tc.AE_INSERT_TS, 
  tc.AE_UPDATE_TS, 
  tc.AE_TRANSACTION_ID, 
  tc.FUNCTIONAL_AREA_UUID, 
  tc.TEST_SET_UUID, 
  tc.TEST_CASE_SEQ_ID, 
  tc.TEST_CASE_STATUS, 
  tc.TEST_CASE_EXECUTON_TYPE,
  tc.ASSOCIATED_VIEW_UUID, 
  'Test Case' as GRID_NAME,
  tc.SKIP_STEP_WITH_NO_UI_ELEMENT_VALUE,
  tc.USER_STORY_UUID,
  ts.PROCESS_UUID,
  ts.PAGE_UUID,
  ts.VIEW_UUID,
  ts.USER_ACTION_UUID
FROM 
  TEST_CASE tc JOIN TEST_SET ts ON tc.TEST_SET_UUID = ts.TEST_SET_UUID
WHERE 
'User Story Test Set' ='Unit Functional Test Set' AND
tc.USER_STORY_UUID LIKE CONCAT('%', :TEST_SET_USER_STORY_UUID, '%')
UNION
SELECT 
  'Unit Functional Test Set' as PARENT_GRID_NAME, 
  'LinkedTestCases' as LINKED_TEST_CASE_GRID, 
  'AllRequirement' as ALL_REQ_GRID,
  'TEST_CASE' as SOURCE_TYPE, 
  'Copy Test Case' as TEST_CASE_FORM_TYPE,
  'Copy Test Case Steps' as TEST_CASE_STEP_FORM_TYPE,
  :TEST_SET_NAME as TEST_SET_NAME,
  TEST_CASE_UUID, 
  TEST_CASE_ID, 
  TEST_CASE_NAME, 
  AE_INSERT_ID, 
  AE_UPDATE_ID, 
  AE_INSERT_TS, 
  AE_UPDATE_TS, 
  AE_TRANSACTION_ID, 
  FUNCTIONAL_AREA_UUID, 
  TEST_SET_UUID, 
  TEST_CASE_SEQ_ID, 
  :PROCESS_UUID as PROCESS_UUID, 
  :PAGE_UUID as PAGE_UUID, 
  :VIEW_UUID as VIEW_UUID, 
  :USER_ACTION_UUID as USER_ACTION_UUID, 
  TEST_CASE_STATUS, 
  TEST_CASE_EXECUTON_TYPE,
  ASSOCIATED_VIEW_UUID, 
  'Test Case' as GRID_NAME,
  SKIP_STEP_WITH_NO_UI_ELEMENT_VALUE,
  USER_STORY_UUID
FROM 
  TEST_CASE 
WHERE 
  TEST_SET_UUID ="af4adbfc-f022-40d3-a82f-2e98f36a92e7" 
  AND TEST_CASE_OWNER IS NULL 
  AND (
    'Unit Functional Test Set' ='Unit Functional Test Set' || 'Orphan Test Set' ='Unit Functional Test Set' || 'Test Set' ='Unit Functional Test Set' || "Page Navigation Test Set" = 'Unit Functional Test Set'
  ) 
UNION 
SELECT 
  'Unit Functional Test Set' as PARENT_GRID_NAME, 
  'LinkedTestCases' as LINKED_TEST_CASE_GRID, 
  'AllRequirement' as ALL_REQ_GRID, 
  'TEST_CASE' as SOURCE_TYPE, 
  'Copy Test Case' as TEST_CASE_FORM_TYPE,
  'Copy Test Case Steps' as TEST_CASE_STEP_FORM_TYPE,
