  TEST_CASE 
WHERE 
  TEST_SET_UUID ="af4adbfc-f022-40d3-a82f-2e98f36a92e7" 
  AND TEST_CASE_OWNER IS NOT NULL 
  AND (
    'Personal Test Set' ='Unit Functional Test Set' || 'Personal - Regular Test Set' ='Unit Functional Test Set' || 'Personal - Unit Functional Test Set' ='Unit Functional Test Set' || 'Personal - Orphan Test Set' ='Unit Functional Test Set'
  ) 
  AND TEST_CASE_OWNER ='DF' 
order by 
  TEST_CASE_ID desc







