  SELECT 
  (SELECT COUNT(REQUIREMENT_TITLE_UUID) FROM REQUIREMENT_TITLE WHERE ) AS R1,
  'FEATURES' AS R2,
  'Requirements' AS R3C1,
  (SELECT COUNT(REQUIREMENT_UUID) 
   FROM REQUIREMENT 
   WHERE REQUIREMENT_ASSOCIATION_TYPE = 'FEATURE') AS R3C2,
  'Implementation Coverage' AS R4C1,
  ROUND(
    (CAST((
      SELECT COUNT(DISTINCT REQUIREMENT_TITLE_UUID) 
      FROM IMPACTED_PROCESS 
      WHERE ASSOCIATION_TYPE = 'FEATURE'
    ) AS FLOAT) * 100.0) / 
    NULLIF((
      SELECT COUNT(REQUIREMENT_UUID) 
      FROM REQUIREMENT 
      WHERE REQUIREMENT_ASSOCIATION_TYPE = 'FEATURE'
    ), 0),
    2
  ) AS R4C2,
  'Test Coverage' AS R5C1,
  ROUND(
    (CAST((
      SELECT COUNT(DISTINCT req.REQUIREMENT_UUID)
      FROM TEST_CASE_REQUIREMENT tcr
      JOIN REQUIREMENT req ON tcr.REQUIREMENT_UUID = req.REQUIREMENT_UUID
      WHERE req.REQUIREMENT_ASSOCIATION_TYPE = 'FEATURE'
    ) AS FLOAT) * 100.0) /
    NULLIF((
      SELECT COUNT(REQUIREMENT_UUID) 
      FROM REQUIREMENT 
      WHERE REQUIREMENT_ASSOCIATION_TYPE = 'FEATURE'
    ), 0),
    2
  ) AS R5C2;






